import sys
from math import inf
from collections import defaultdict

class disjoinSet(object):

	def __init__(self, n):
		self.father = [x for x in range(0, n + 1)]
		self.rank = [0 for x in range(0, n + 1)]

	def setOf(self, x):
		if self.father[x] != x:
			self.father[x] = self.setOf(self.father[x])
		return self.father[x]

	def Merge(self, x, y):
		xR = self.setOf(x)
		yR = self.setOf(y)
		if xR == yR:
			return
		if self.rank[xR] < self.rank[yR]:
			self.father[xR] = yR
		elif self.rank[xR] > self.rank[yR]:
			self.father[yR] = xR
		else:
			self.father[yR] = xR
			self.rank[xR] += 1

def merge(left, right):
	result = []
	(l, r) = (0, 0)
	while l < len(left) and r < len(right):
		if left[l][2] <= right[r][2]:
			result.append(left[l])
			l += 1
		else:
			result.append(right[r])
			r += 1
	result += left[l:]
	result += right[r:]
	return result

def mergesort(x):
	if len(x) < 2:
		return x
	middle = int(len(x) / 2)
	left = mergesort(x[:middle])
	right = mergesort(x[middle:])
	return merge(left, right)

def DFS(graph, bridges):
	time = 0
	for key in graph:
		low[key] = inf
		d[key] = -1
		pi[key] = key
		visited[key] = False
	for i in graph:
		if not visited[i]:
			DFS_Visit(graph, i, bridges)

def DFS_Visit(graph, u, bridges):
	visited[u] = True
	global time
	time += 1
	d[u] = time
	low[u] = d[u]
	for v in graph[u]:
		if not visited[v]:
			pi[v] = u
			DFS_Visit(graph, v, bridges)
			low[u] = min(low[u], low[v])
		elif pi[u] != v:
			low[u] = min(low[u], d[v])
	if pi[u] != u and low[u] >= d[u]:
		x = min(pi[u], u)
		y = max(pi[u], u)
		bridges.append([x, y])
	time += 1
time = 0
(n, m) = map(int, sys.stdin.readline().split())
if m <= n - 1:
	for _ in range(0, m):
		print('any')
	exit()
visited = {}
d = {}
low = {}
pi = {}
edges = []
for i in range(0, m):
	(x, y, z) = map(int, sys.stdin.readline().split())
	edges.append([])
	edges[i] = [x, y, z]
dsu = disjoinSet(n)
ans = {}
for i in edges:
	x = min(i[0], i[1])
	y = max(i[0], i[1])
	ans[x, y] = 'at least one'
sortEdges = mergesort(edges)
criticalEdges = []
i = 0
cantEdges = m
while i < cantEdges:
	j = i
	a = 0
	b = 0
	criticalEdges = []
	while j < len(sortEdges) and sortEdges[j][2] == sortEdges[i][2]:
		x = dsu.setOf(sortEdges[j][0])
		y = dsu.setOf(sortEdges[j][1])
		a = min(sortEdges[j][0], sortEdges[j][1])
		b = max(sortEdges[j][0], sortEdges[j][1])
		if x == y:
			ans[a, b] = 'none'
		criticalEdges.append(sortEdges[j])
